from numpy import array
def saisie_n():
    n=int(input("Donner le nombre de lignes et de colonnes: "))
    while not (3<=n<20):
        n=int(input("Donner le nombre de lignes et de colonnes: "))
    return n

def remplir(n):
    M=array([[int()]*n]*n)
    #initialisation de matrice à 0
    for i in range(n):
        for j in range(n):
            M[i,j]=0
    #initialiser la premiere colonne en 1
    for i in range(n):
        M[i,0]=1
    #Remplissage de triangle de pascale
    for i in range(1,n):
        for j in range(1,n):
            M[i,j]=M[i-1,j]+M[i-1,j-1]
    return M

def afficher(M,n):
    for i in range(n):
        for j in range(n):
            print(M[i,j],end="  ")
        print()

#Programme Principale
n=saisie_n()
M=remplir(n)
afficher(M,n)

